import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  let trialId: string;
  try {
    const rawTrialId = await readFile("/logs/artifacts/trial_id", "utf-8");
    trialId = rawTrialId.trim();
  } catch (error) {
    console.error("Failed to read trial_id:", error);
    process.exit(1);
  }

  const workspaceName = `harbor-ws-${trialId}`;

  const { data: workspace, error: wsError } = await createWorkspace(workspaceName, {
    ttl: { days: 1 },
    credentials: { role: "Editor" },
  });

  if (wsError || !workspace || !workspace.credentials) {
    console.error("Failed to create workspace:", wsError || "No workspace or credentials returned");
    process.exit(1);
  }

  const { bucket, credentials } = workspace;
  const { accessKeyId, secretAccessKey } = credentials;

  const objectKey = "state.json";
  const body = `{"status":"ok","run":"${trialId}"}`;

  const { error: putError } = await put({
    key: objectKey,
    body,
    contentType: "application/json",
  }, {
    bucket,
    accessKeyId,
    secretAccessKey,
  });

  if (putError) {
    console.error("Failed to upload object:", putError);
    process.exit(1);
  }

  console.log(accessKeyId);
  try {
    await writeFile("/home/user/tigris-task/output.log", accessKeyId);
  } catch (error) {
    console.error("Failed to write to output.log:", error);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error("Unhandled error:", error);
  process.exit(1);
});
